import XCTest

final class ReactionTests: XCTestCase {
    func testAddReaction() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        XCTAssertTrue(app.waitForExistence(timeout: 10))
        sleep(2)
        let back = app.buttons["All chats"]
        if back.exists { back.tap(); sleep(2) }
        let roomCell = app.cells.containing(NSPredicate(format: "label CONTAINS[c] %@", "Team Standup")).firstMatch
        if roomCell.waitForExistence(timeout: 5) { roomCell.tap(); sleep(2) }
        let message = app.textViews.matching(NSPredicate(format: "value CONTAINS[c] %@", "No blockers from me")).firstMatch
        XCTAssertTrue(message.waitForExistence(timeout: 5))
        let point = message.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
        point.press(forDuration: 1.2)
        sleep(2)
        print("REACTION_MENU_TREE_BEGIN\n\(app.debugDescription)\nREACTION_MENU_TREE_END")
        XCTAssertTrue(app.exists)
    }
}
EOF
